import csv, io, json, sys

def summarize(payload):
    values = [float(row[payload['column']]) for row in csv.DictReader(io.StringIO(payload['csv']))]
    return {'count': len(values), 'total': sum(values), 'average': sum(values) / len(values) if values else 0}

if __name__ == '__main__':
    print(json.dumps(summarize(json.load(sys.stdin))))
